import{_ as a,o,c as i,ae as r}from"./chunks/framework.RRduUuAx.js";const p=JSON.parse('{"title":"Runtime Performance Baselines (WP06)","description":"","frontmatter":{},"headers":[],"relativePath":"runtime-performance-baselines.md","filePath":"runtime-performance-baselines.md"}'),s={name:"runtime-performance-baselines.md"};function t(l,e,n,c,d,u){return o(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="runtime-performance-baselines-wp06" tabindex="-1">Runtime Performance Baselines (WP06) <a class="header-anchor" href="#runtime-performance-baselines-wp06" aria-label="Permalink to &quot;Runtime Performance Baselines (WP06)&quot;">​</a></h1><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>This document defines WP06 soak thresholds and failure criteria for slice-1 runtime hardening.</p><h2 id="soak-scenario" tabindex="-1">Soak Scenario <a class="header-anchor" href="#soak-scenario" aria-label="Permalink to &quot;Soak Scenario&quot;">​</a></h2><p>Command:</p><ul><li><code>bun test apps/runtime/tests/soak/multi_session_soak.test.ts</code></li></ul><p>Workload profile:</p><ul><li>200 lane create commands in concurrent batches.</li><li>200 session restore attach commands in concurrent batches across multiple session IDs.</li><li>300 terminal output events with bounded waveform plus periodic spike pressure.</li></ul><h2 id="baseline-thresholds" tabindex="-1">Baseline Thresholds <a class="header-anchor" href="#baseline-thresholds" aria-label="Permalink to &quot;Baseline Thresholds&quot;">​</a></h2><ul><li><code>lane_create_latency_ms</code>: <code>p95 &lt;= 30ms</code></li><li><code>session_restore_latency_ms</code>: <code>p95 &lt;= 35ms</code></li><li><code>terminal_output_backlog_depth</code>: <code>p95 &lt;= 64</code></li></ul><p>Notes:</p><ul><li>Spike samples above <code>64</code> are expected in low frequency; gate validity is determined by <code>p95</code>, not <code>max</code>.</li><li>Session restore latency keeps a strict <code>35ms</code> target. If first-run <code>p95</code> is within <code>+3ms</code> jitter band, rerun once and require strict <code>p95 &lt;= 35ms</code> on the retry to avoid host-noise flakes.</li></ul><h2 id="failure-criteria" tabindex="-1">Failure Criteria <a class="header-anchor" href="#failure-criteria" aria-label="Permalink to &quot;Failure Criteria&quot;">​</a></h2><p>Any one of the following is a hard failure:</p><ol><li>Missing metric summary for any required metric.</li><li><code>p95</code> above threshold for lane create latency.</li><li><code>p95</code> above threshold for session restore latency.</li><li><code>p95</code> above threshold for backlog depth.</li></ol><h2 id="triage-notes" tabindex="-1">Triage Notes <a class="header-anchor" href="#triage-notes" aria-label="Permalink to &quot;Triage Notes&quot;">​</a></h2><ol><li>Reproduce with focused unit + soak commands.</li><li>Check <code>diagnostics.metric</code> event density in bus event log.</li><li>For backlog spikes, inspect output producer pacing and backpressure boundaries.</li><li>For latency drift, inspect synchronous work inside lifecycle handlers.</li></ol>',17)])])}const m=a(s,[["render",t]]);export{p as __pageData,m as default};
